/** By id, for O(1) lookup from the trace and the 3D scene. */
export const ARCH_NODE_BY_ID: ReadonlyMap<string, ArchNode> = new Map(
  ARCH_NODES.map((n) => [n.id, n]),
);

/**
 * One command word, with everything the trace needs to explain it.
 *
 * `logBanner` is what the firmware actually prints on entry - the first
 * `log` step of the movement function. It is how `movement.enter` can be
 * OBSERVED rather than asserted: under QEMU the guest really writes it to
 * UART0, and the simulator emits the same string from the same extracted
 * step, so one row works on both backends and says which it got.
 */
export interface CommandTraceFacts {
  readonly command: string;
  readonly movementFunction: string | null;
  readonly movementSourceRef: ArchSourceRef | null;
  readonly movementSourceRange: { readonly file: string; readonly from: number; readonly to: number } | null;
  readonly commandSourceRef: ArchSourceRef | null;
  readonly logBanner: string | null;
  readonly logBannerSourceRef: ArchSourceRef | null;
  readonly faceOnEntry: string | null;
  readonly joints: readonly string[];
  readonly servoStepCount: number;
  readonly stepCount: number;
  readonly continuous: boolean;
  readonly clearsSelf: boolean;
}

